        public readonly bool Equals(uint3 rhs) => x == rhs.x && y == rhs.y && z == rhs.z;
        public override readonly bool Equals(object o) => o is uint3 converted && Equals(converted);
        public override readonly int GetHashCode() => (int)math.hash(this);
        public override readonly string ToString() => string.Format("uint3({0}, {1}, {2})", x, y, z);
        public readonly string ToString(string format, IFormatProvider formatProvider) =>
            string.Format("uint3({0}, {1}, {2})", x.ToString(format, formatProvider), y.ToString(format, formatProvider), z.ToString(format, formatProvider));
    }
}
